import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, uniform, positionLocal, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Vector3, Color, Raycaster, Vector2 } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }]
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }];
  // Use a lighter top gradient to avoid a dark gray blob dominating the upper half
  const topHex = paper; // brighter top (paper) instead of dark stop
  const botHex = stops[stops.length - 1].hex;
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const inactiveHex = '#a6adba';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labels = items.length
    ? items.map((it) => (typeof it === 'string' ? it : it.text))
    : ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const hubTargets = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];

  const root = new Group();
  root.name = 'nav-dock';

  // --- Backdrop stage plane (vertical gradient) ---
  const bgMat = new MeshBasicNodeMaterial();
  const cTop = uniform(new Color(topHex));
  const cBot = uniform(new Color(botHex));
  bgMat.colorNode = mix(cBot, cTop, uv().y);
  const bg = new Mesh(new PlaneGeometry(7, 6), bgMat);
  bg.position.set(0, 0, -2.5);
  root.add(bg);

  // --- Lights (node-local rim/key) ---
  const ambient = new AmbientLight(0xffffff, 0.5);
  root.add(ambient);
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(-2.5, 3, 4);
  root.add(key);
  const rim = new DirectionalLight(new Color(accent), 1.1);
  rim.position.set(3, -1.5, 2.5);
  root.add(rim);

  // --- Contact shadow plane ---
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const sc = uniform(new Color('#000000'));
  const suv = uv();
  const dx = suv.x.sub(0.5).abs();
  const dy = suv.y.sub(0.5).abs();
  const falloff = dx.max(dy.mul(3.0)).oneMinus().clamp(0, 1);
  shadowMat.colorNode = vec4(sc, falloff.mul(0.35));
  const shadow = new Mesh(new PlaneGeometry(4.0, 0.7), shadowMat);
  shadow.position.set(0, -0.06, 0.02);
  root.add(shadow);

  // --- Machined rail ---
  const railGroup = new Group();
  railGroup.position.z = 0.15;
  root.add(railGroup);

  const railMat = new MeshStandardNodeMaterial();
  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  const railTop = uniform(new Color(topHex));
  railTop.value = new Color('#1b1b23');
  const railBot = uniform(new Color(botHex));
  railBot.value = new Color('#101015');
  // vertical albedo ramp using local position y
  const py = positionLocal.y.mul(2.0).add(0.5).clamp(0, 1);
  railMat.colorNode = mix(railBot, railTop, py);

  const rail = new Mesh(new BoxGeometry(3.6, 0.5, 0.12), railMat);
  railGroup.add(rail);

  // chamfer highlight strip (thin bright box catching key)
  const chamMat = new MeshStandardNodeMaterial();
  chamMat.metalness = 0.5;
  chamMat.roughness = 0.35;
  chamMat.color = new Color('#2a2a36');
  const cham = new Mesh(new BoxGeometry(3.6, 0.02, 0.13), chamMat);
  cham.position.y = 0.24;
  railGroup.add(cham);

  // --- Entries ---
  const spacing = 0.68;
  const startX = -((labels.length - 1) * spacing) / 2;
  const cells = [];
  let activeIndex = 0;

  for (let i = 0; i < labels.length; i++) {
    const cell = new Group();
    cell.position.set(startX + i * spacing, 0, 0.07);
    railGroup.add(cell);

    // invisible hit cell (basic mat, tiny opacity)
    const hitMat = new MeshBasicNodeMaterial();
    hitMat.transparent = true;
    hitMat.opacity = 0.0;
    const hit = new Mesh(new PlaneGeometry(0.6, 0.34), hitMat);
    hit.userData.cellIndex = i;
    cell.add(hit);

    const isActive = i === activeIndex;
    const txt = ctx.fontAtlas.createText(labels[i], {
      fontSize: 26,
      color: isActive ? paper : inactiveHex,
      align: 'center',
      letterSpacingPx: 2
    });
    txt.scale.setScalar(0.5);
    txt.position.set(0, 0.01, 0.02);
    cell.add(txt);

    cells.push({ cell, hit, txt, index: i });
  }

  // --- Active underline bar ---
  const barMat = new MeshStandardNodeMaterial();
  barMat.color = new Color(accent);
  barMat.emissive = new Color(accent);
  barMat.emissiveIntensity = 1.8;
  barMat.roughness = 0.5;
  barMat.metalness = 0.0;
  const bar = new Mesh(new BoxGeometry(0.28, 0.025, 0.02), barMat);
  bar.position.set(startX + activeIndex * spacing, -0.14, 0.09);
  railGroup.add(bar);

  // --- Mount animation (rise-in) ---
  const tls = [];
  railGroup.position.y = 0.4;
  const mountTl = gsap.timeline();
  mountTl.fromTo(railGroup.position, { y: 0.4 }, { y: 0.0, duration: 0.7, ease: 'power3.out' });
  mountTl.fromTo(railGroup.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tls.push(mountTl);

  // idle breathing (single slow transform)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(railGroup.position, { z: 0.17, duration: 3.0, ease: 'sine.inOut' });
  tls.push(idleTl);

  // --- Interaction helpers ---
  function setActive(index) {
    if (index === activeIndex) return;
    // color swap
    cells[activeIndex].txt.traverse((o) => { if (o.material && o.material.color) o.material.color.set(inactiveHex); });
    cells[index].txt.traverse((o) => { if (o.material && o.material.color) o.material.color.set(paper); });
    activeIndex = index;
    // slide underline with overshoot
    gsap.to(bar.position, {
      x: startX + index * spacing,
      duration: 0.26,
      ease: 'back.out(1.4)'
    });
  }

  function pressCell(index) {
    const c = cells[index].cell;
    gsap.timeline()
      .to(c.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(c.position, { z: 0.04, duration: 0.12, ease: 'power2.out' }, 0)
      .to(c.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' })
      .to(c.position, { z: 0.07, duration: 0.2, ease: 'power2.out' }, '<');
  }

  function hoverCell(index, on) {
    if (index === activeIndex) return;
    cells[index].txt.traverse((o) => {
      if (o.material && o.material.color) {
        gsap.to(o.material.color, {
          r: on ? new Color(paper).r : new Color(inactiveHex).r,
          g: on ? new Color(paper).g : new Color(inactiveHex).g,
          b: on ? new Color(paper).b : new Color(inactiveHex).b,
          duration: 0.16, ease: 'power2.out'
        });
      }
    });
  }

  // --- Raycast-based handlers ---
  const raycaster = new Raycaster();
  const ndc = new Vector2();
  let hovered = -1;

  function pick(payload) {
    if (!payload || !payload.camera) return -1;
    if (payload.ndc) { ndc.set(payload.ndc.x, payload.ndc.y); }
    else if (payload.x !== undefined) { ndc.set(payload.x, payload.y); }
    raycaster.setFromCamera(ndc, payload.camera);
    const hits = raycaster.intersectObjects(cells.map((c) => c.hit), false);
    if (hits.length) return hits[0].object.userData.cellIndex;
    return -1;
  }

  root.userData.handlers = {
    pointermove(payload) {
      const idx = pick(payload);
      if (idx !== hovered) {
        if (hovered >= 0) hoverCell(hovered, false);
        if (idx >= 0) hoverCell(idx, true);
        hovered = idx;
      }
    },
    pointerdown(payload) {
      const idx = pick(payload);
      if (idx >= 0) pressCell(idx);
    },
    click(payload) {
      const idx = pick(payload);
      if (idx >= 0) {
        setActive(idx);
        ctx.emit('navigate', { to: hubTargets[idx] ?? hubTargets[0] });
      }
    }
  };

  root.userData.setActive = setActive;

  root.userData.cleanup = function () {
    for (const t of tls) t.kill();
    gsap.killTweensOf(bar.position);
    cells.forEach((c) => {
      gsap.killTweensOf(c.cell.scale);
      gsap.killTweensOf(c.cell.position);
    });
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  };

  return root;
}
